static float interpolatePixels (float V00, float V10, float V01, float V11, float dx, float dy) {
    // bilinear interpolation
    float rx = 1.0 - dx;
    float ry = 1.0 - dy;
    float value = V00*rx*ry + V10*dx*ry + V01*rx*dy + V11*dx*dy;
    return value;
}

